import{_ as e,o as t,c as a,ae as n}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-07-02","description":"","frontmatter":{"date":"2026-07-02T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-07-02-uxtrend.md","filePath":"daily/2026-07-02-uxtrend.md"}'),o={name:"daily/2026-07-02-uxtrend.md"};function s(i,r,g,p,h,l){return t(),a("div",null,[...r[0]||(r[0]=[n('<h1 id="设计趋势-2026-07-02" tabindex="-1">设计趋势 - 2026-07-02 <a class="header-anchor" href="#设计趋势-2026-07-02" aria-label="Permalink to &quot;设计趋势 - 2026-07-02&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势领域聚焦于代理型用户体验（UX）设计和AI在设计工作流程中的应用。其中，代理型UX设计强调人机信任的协调，而非传统界面和功能，预示着设计认知的重大转变。同时，AI技术显著提升了设计效率，并助力创造更用户友好的AI产品。最值得关注的是代理型UX设计的理念革新以及AI技术在设计领域的深度融合。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 设计原则指导数字设备中的新型用户体验</p><p><strong>能解决什么问题</strong>: 解决数字代理系统中用户体验设计的独特挑战</p><p><strong>产品应用</strong>: 适用于产品开发，以人为中心，加速智能系统开发</p><p><strong>示例场景</strong>: 智能助手协助用户进行知识更新和情绪调节</p><hr><h3 id="_2-为什么代理型ux将改变你对设计的所有认知" tabindex="-1">2. 为什么代理型UX将改变你对设计的所有认知 <a class="header-anchor" href="#_2-为什么代理型ux将改变你对设计的所有认知" aria-label="Permalink to &quot;2. 为什么代理型UX将改变你对设计的所有认知&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/generative-ai-revolution-ai-native-transformation/why-agentic-ux-will-change-everything-you-know-about-design-0394486f5add" target="_blank" rel="noreferrer">Why Agentic UX Will Change Everything You Know About Design</a></p><p><strong>一句话摘要</strong>: 代理型UX设计关注于人机信任的协调，而非界面和功能。</p><p><strong>能解决什么问题</strong>: 如何让用户接受、信任并有效利用AI代理。</p><p><strong>产品应用</strong>: 适用于需要人机协作的智能系统，如企业自动化流程。</p><p><strong>示例场景</strong>: 智能预算系统提示用户是否提交Q3预算。</p><hr><h3 id="_3-ai如何改变我的设计工作流程" tabindex="-1">3. AI如何改变我的设计工作流程 <a class="header-anchor" href="#_3-ai如何改变我的设计工作流程" aria-label="Permalink to &quot;3. AI如何改变我的设计工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@kazdenc/how-my-design-workflow-is-changing-with-ai-bc80e7fa3323" target="_blank" rel="noreferrer">How my design workflow is changing with AI</a></p><p><strong>一句话摘要</strong>: AI让设计工作流程更快速、协作和实用。</p><p><strong>能解决什么问题</strong>: 提高设计效率，减少猜测，增加实际测试。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过快速原型迭代提升产品质量。</p><p><strong>示例场景</strong>: 设计师使用Figma和Cursor工具进行快速原型设计。</p><hr><h3 id="_4-ai与设计-人工智能如何协助设计师以及设计师如何创造ai友好产品" tabindex="-1">4. AI与设计：人工智能如何协助设计师以及设计师如何创造AI友好产品 <a class="header-anchor" href="#_4-ai与设计-人工智能如何协助设计师以及设计师如何创造ai友好产品" aria-label="Permalink to &quot;4. AI与设计：人工智能如何协助设计师以及设计师如何创造AI友好产品&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@gwrx2005/ai-and-design-how-artificial-intelligence-assists-designers-and-how-designers-create-ai-friendly-df97320884ae" target="_blank" rel="noreferrer">AI and Design: How Artificial Intelligence Assists Designers and How Designers Create AI‑Friendly…</a></p><p><strong>一句话摘要</strong>: AI技术在设计领域的应用，提升设计效率并创造用户友好的AI产品。</p><p><strong>能解决什么问题</strong>: 解决设计过程中的复杂问题，提高效率，同时确保AI系统的易用性和信任度。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI辅助设计和优化用户体验。</p><p><strong>示例场景</strong>: 设计一个基于AI的聊天机器人，提升客户服务效率。</p><hr><h3 id="_5-ai代理工作流设计模式概览" tabindex="-1">5. AI代理工作流设计模式概览 <a class="header-anchor" href="#_5-ai代理工作流设计模式概览" aria-label="Permalink to &quot;5. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，分类并举例说明。</p><p><strong>能解决什么问题</strong>: 如何设计能模拟人类推理的AI代理工作流。</p><p><strong>产品应用</strong>: 可应用于开发灵活的任务协调器，处理不同问题。</p><p><strong>示例场景</strong>: 使用ReAct模式集成工具增强AI代理能力。</p><hr><h3 id="_6-为人工智能设计-设计人工智能特性的交互" tabindex="-1">6. 为人工智能设计：设计人工智能特性的交互 <a class="header-anchor" href="#_6-为人工智能设计-设计人工智能特性的交互" aria-label="Permalink to &quot;6. 为人工智能设计：设计人工智能特性的交互&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@ux.haowu/design-for-ai-2-designing-interactions-for-ai-features-d776d6388bdd" target="_blank" rel="noreferrer">Design for AI 2: Designing Interactions for AI Features</a></p><p><strong>一句话摘要</strong>: AI通过预测意图和实时补全，辅助用户保持专注。</p><p><strong>能解决什么问题</strong>: 解决用户在快节奏工作流中快速输入和减少错误的问题。</p><p><strong>产品应用</strong>: 可以应用到需要快速输入和减少错误的场景，如电子邮件客户端和编程应用。</p><p><strong>示例场景</strong>: 在Figma中自动补全地址，减少打字和输入错误。</p><hr><h3 id="_7-代理式用户体验-为代理系统设计7原则" tabindex="-1">7. 代理式用户体验：为代理系统设计7原则 <a class="header-anchor" href="#_7-代理式用户体验-为代理系统设计7原则" aria-label="Permalink to &quot;7. 代理式用户体验：为代理系统设计7原则&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/agentic-ux-7-principles-for-designing-systems-with-agents-019512c2caa9" target="_blank" rel="noreferrer">Agentic UX: 7 principles for designing systems with agents</a></p><p><strong>一句话摘要</strong>: 设计代理系统时，需确保上下文双向流通，以增强信任感。</p><p><strong>能解决什么问题</strong>: 解决代理系统在用户体验中的上下文断裂和信任问题。</p><p><strong>产品应用</strong>: 适用于需要智能代理辅助的任何产品，如客服机器人。</p><p><strong>示例场景</strong>: 在线客服系统中的智能助手自动回答问题。</p><hr><h3 id="_8-ai在设计中的应用-改变我们的创造方式" tabindex="-1">8. AI在设计中的应用：改变我们的创造方式 <a class="header-anchor" href="#_8-ai在设计中的应用-改变我们的创造方式" aria-label="Permalink to &quot;8. AI在设计中的应用：改变我们的创造方式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/ai-in-design" target="_blank" rel="noreferrer">AI in Design: Transforming the Way We Create - Figma</a></p><p><strong>一句话摘要</strong>: AI技术将深度整合进设计工作流程，提升创造力。</p><p><strong>能解决什么问题</strong>: 提高设计效率，减少重复性工作，增强个性化体验。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI辅助生成设计选项，优化用户体验。</p><p><strong>示例场景</strong>: 设计师使用AI生成多种界面布局，快速响应用户需求。</p><hr><h3 id="_9-2026年顶级网页设计趋势-figma" tabindex="-1">9. 2026年顶级网页设计趋势 | Figma <a class="header-anchor" href="#_9-2026年顶级网页设计趋势-figma" aria-label="Permalink to &quot;9. 2026年顶级网页设计趋势 | Figma&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/web-design-trends" target="_blank" rel="noreferrer">Top Web Design Trends for 2026 | Figma</a></p><p><strong>一句话摘要</strong>: AI技术使网页设计更智能、个性化。</p><p><strong>能解决什么问题</strong>: 提升用户体验，实现网站功能自动化和个性化。</p><p><strong>产品应用</strong>: 可应用于网站设计，通过AI工具优化布局、交互和用户旅程。</p><p><strong>示例场景</strong>: 使用Figma Make测试智能布局和AI驱动体验。</p><hr><h3 id="_10-ai交互模式-让用户识别和与ai驱动功能互动" tabindex="-1">10. AI交互模式：让用户识别和与AI驱动功能互动 <a class="header-anchor" href="#_10-ai交互模式-让用户识别和与ai驱动功能互动" aria-label="Permalink to &quot;10. AI交互模式：让用户识别和与AI驱动功能互动&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@flik185/ai-interaction-patterns-giving-users-ways-to-recognize-and-interact-with-ai-driven-features-22055a91206b" target="_blank" rel="noreferrer">AI Interaction Patterns: Giving Users Ways to Recognize and Interact With Ai-Driven Features</a></p><p><strong>一句话摘要</strong>: 通过交互模式建立人与AI之间的信任关系</p><p><strong>能解决什么问题</strong>: 如何让用户识别并有效利用AI功能</p><p><strong>产品应用</strong>: 适用于AI工具，如聊天机器人、分析仪表板等</p><p><strong>示例场景</strong>: 聊天机器人提供操作提示和反馈</p><hr>',75)])])}const f=e(o,[["render",s]]);export{c as __pageData,f as default};
